package net.zartra.gui;
import org.bukkit.command.PluginCommand;import org.bukkit.entity.Player;import org.bukkit.plugin.java.JavaPlugin;import org.bukkit.Material;import org.bukkit.inventory.ItemStack;import java.io.File;
public final class ZartraGUIPlugin extends JavaPlugin {private MenuManager menus;private GuiService gui;private ChatInputManager inputs;private ZGuiCommand command;private ActionExecutor actions;private VariableStore variables;private VariableStorage variableStorage;private AliasRegistry aliases;private ChatColorPicker colorPicker;private String buildId="unknown";
 public void onEnable(){try{java.util.Properties b=new java.util.Properties();java.io.InputStream stream=getResource("build.properties");if(stream!=null){b.load(stream);stream.close();}buildId=b.getProperty("build-id",getDescription().getVersion());getLogger().info("Build: "+buildId);getLogger().info("Declared API version="+declaredApiVersion()+"; Legacy material mode active="+legacyMaterialMode()+"; Runtime TUFF="+runtimeMaterialProbe()+"; Bukkit Material count="+Material.values().length);getLogger().info("Enabling on "+getServer().getName()+" "+getServer().getVersion()+" (Java "+System.getProperty("java.version")+")");saveDefaultConfig();ServerNameResolver.configure(getConfig().getString("server-name",""));saveResource("messages.yml",false);variables=new VariableStore();variableStorage=new VariableStorage(new File(getDataFolder(),"variables.yml"));variableStorage.load(variables);inputs=new ChatInputManager(getConfig().getLong("chat-input-timeout-seconds",60));menus=new MenuManager(new MenuStorage(new File(getDataFolder(),"menus"),getLogger()));gui=new GuiService(this,menus);colorPicker=new ChatColorPicker(this,gui);actions=new ActionExecutor(this,menus);menus.runtime(this,actions);getServer().getMessenger().registerOutgoingPluginChannel(this,"BungeeCord");command=new ZGuiCommand(this,menus,gui);PluginCommand root=getCommand("zgui");if(root==null)throw new IllegalStateException("plugin.yml does not declare zgui");root.setExecutor(command);root.setTabCompleter(command);PluginCommand internal=getCommand("_zgui_picker");if(internal==null)throw new IllegalStateException("plugin.yml does not declare internal picker command");internal.setExecutor(new org.bukkit.command.CommandExecutor(){public boolean onCommand(org.bukkit.command.CommandSender s,org.bukkit.command.Command c,String l,String[] a){return command.internalPicker(s,a);}});aliases=new AliasRegistry(this,menus);aliases.refresh();getServer().getPluginManager().registerEvents(new GuiListener(this,menus,gui),this);getLogger().info("Enabled: "+menus.all().size()+" menu(s) loaded; legacy API compatible.");}catch(Exception e){getLogger().severe("Failed to enable ZartraGUI: "+e.getMessage());e.printStackTrace();getServer().getPluginManager().disablePlugin(this);}}
 String buildId(){return buildId;} String declaredApiVersion(){try{java.lang.reflect.Method m=getDescription().getClass().getMethod("getAPIVersion");Object value=m.invoke(getDescription());return value==null?"none":String.valueOf(value);}catch(Throwable ignored){return "none";}} String runtimeMaterialProbe(){try{Material material=Material.valueOf("TUFF");ItemStack stack=new ItemStack(material,64),clone=stack.clone(),round=ItemStack.deserialize(stack.serialize());return material.name()+"/"+stack.getType().name()+"/"+clone.getType().name()+"/"+round.getType().name();}catch(Throwable ignored){return "unavailable";}} boolean legacyMaterialMode(){return "none".equals(declaredApiVersion());} MenuManager menus(){return menus;} ChatColorPicker colorPicker(){return colorPicker;} void askCreate(final Player p){gui.requestInput(p,"&eEnter a lowercase menu ID.",new ChatInputManager.Callback(){public void run(Player who,String text){command.create(who,text);}});} ChatInputManager inputs(){return inputs;} ActionExecutor actions(){return actions;} VariableStore variables(){return variables;} void refreshAliases(){if(aliases!=null)aliases.refresh();} public void onDisable(){if(aliases!=null)aliases.clear();if(menus!=null)menus.shutdown();if(inputs!=null)inputs.clear();if(colorPicker!=null)colorPicker.clearAll();if(gui!=null)gui.clearLeatherSessions();try{if(variableStorage!=null)variableStorage.save(variables);}catch(Exception e){getLogger().warning("Variable save failed: "+e.getMessage());}try{if(menus!=null)for(MenuDefinition d:menus.all())menus.save(d);}catch(Exception e){getLogger().warning("Save during shutdown failed: "+e.getMessage());}}
}
